<article class="card"><h2>Tendencia reciente</h2><?php if(!$dockerHistory): ?><p class="muted">Sin historial persistido.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Muestra</th><th>CPU</th><th>Memoria</th><th>RX</th><th>TX</th></tr></thead><tbody><?php foreach($dockerHistory as $x): $a=is_array($x['aggregates']??null)?$x['aggregates']:[]; ?><tr><td><?= docker_h($x['generated_at']??'') ?></td><td><?= docker_h(docker_format_percent($a['cpu_percent']??null)) ?></td><td><?= docker_h(docker_format_bytes($a['memory_used_bytes']??null)) ?></td><td><?= docker_h(docker_format_bytes($a['network_rx_bytes_total']??null)) ?></td><td><?= docker_h(docker_format_bytes($a['network_tx_bytes_total']??null)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></article>
